parameters.jsCode:
const rows = $input.all().map(item => item.json);

// =========================
// HELPER
// =========================

function val(row, key) {
  const value = row?.[key];

  if (value === undefined || value === null) {
    return "";
  }

  return String(value).trim();
}

function findRow(key, value) {
  return rows.find(row => val(row, key) === value) || {};
}

// =========================
// HEADER MANIFEST
// =========================

const manifestRow = rows.find(row =>
  val(row, "__EMPTY").includes("/XII/")
) || {};

const dateRow = findRow("__EMPTY_1", "DATE");
const fromRow = findRow("__EMPTY_1", "FROM");
const toRow = findRow("__EMPTY_1", "TO");

const manifest = {
  manifestNo: val(manifestRow, "__EMPTY"),

  date: val(dateRow, "__EMPTY_2")
    .replace(/^:\s*/, ""),

  from: val(fromRow, "__EMPTY_2")
    .replace(/^:\s*/, ""),

  to: val(toRow, "__EMPTY_2")
    .replace(/^:\s*/, ""),

  flightNo: val(fromRow, "__EMPTY_6")
    .replace(/^:\s*/, "")
};

// =========================
// PREPARED BY
// =========================

const preparedByRow = rows.find(row =>
  val(row, "__EMPTY") === "Prepared by :"
) || {};

const preparedBy =
  val(preparedByRow, "__EMPTY_1") ||
  val(preparedByRow, "__EMPTY_2") ||
  "";

// =========================
// APPROVED BY
// =========================

const approvedByRow = rows.find(row =>
  val(row, "__EMPTY_5") === "Approved by Acceptance:"
) || {};

const approvedBy =
  val(approvedByRow, "__EMPTY_6") ||
  val(approvedByRow, "__EMPTY_7") ||
  "";

// =========================
// STOWING ITEMS
// =========================

const stowingItems = [];

for (const row of rows) {
  const no = val(row, "__EMPTY_7");

  // Hanya baris nomor stowing: 1, 2, 3, dst.
  if (/^\d+$/.test(no)) {
    stowingItems.push({
      no: Number(no),
      noPag: val(row, "__EMPTY_8"),
      description: val(row, "__EMPTY_9"),
      netWeight: val(row, "__EMPTY_10"),
      grossWeight: val(row, "__EMPTY_11"),
      customers: val(row, "__EMPTY_12")
    });
  }
}

// =========================
// TOTAL WEIGHT
// =========================

const totalWeightRow = rows.find(row =>
  val(row, "__EMPTY_7") === "TOTAL WEIGHT"
) || {};

const totalWeight = val(totalWeightRow, "__EMPTY_11");

// =========================
// RESPONSE
// =========================

return [{
  json: {
    success: true,

    message: "Manifest berhasil diproses",

    manifest,

    stowing: {
      totalWeight,
      itemCount: stowingItems.length,
      items: stowingItems
    },

    rawItemCount: rows.length
  }
}];

const body = $json.body || {};
const items = body.items || [];

return items
  .filter(item =>
    item.noPag &&
    item.description &&
    item.pcsQty !== undefined &&
    item.pcsQty !== null
  )
  .map(item => ({
    json: {
      container: String(item.noPag),
      cargo: String(item.description),
      quantity: item.pcsQty,
      customer: item.customer || "",
      pti: item.pti || "",
      weight: item.weight || "",
      subTotal: item.subTotal || ""
    }
  }));
